    private function encodeAudioSegment(array $job): string
    {
        $outputPath = $job['output_path'];
        $dir = dirname($outputPath);
        if (!is_dir($dir)) {
            mkdir($dir, 0755, true);
        }

        // Also refresh the audio init segment. The HLS muxer init depends only
        // on codec configuration, so every segment encode produces an identical
        // init file. Keeping it fresh avoids races where the init is missing or
        // was written by an older code path.
        $initPath = $dir . '/init.mp4';

        $encodeResult = $this->encodeFmp4AudioSegment(
            $job['source_path'],
            (float) $job['start_time'],
            (float) $job['duration'],
            $job,
            $outputPath,
            false,
            $initPath,
        );

        $metrics = $this->parseFfmpegMetrics($encodeResult['stderr'] ?? '');

        return json_encode([
            'success' => true,
            'output_path' => $outputPath,
            'metrics' => $metrics,
            'duration' => $encodeResult['duration'],
        ]);
    }

