/**
 * Encode an audio segment using ffmpeg's HLS muxer with fmp4 segments.
 *
 * Audio-only encodes do not naturally fragment with raw -f mp4 because
 * audio lacks keyframes. The HLS muxer produces valid CMAF audio fragments
 * (styp + sidx + moof + mdat) sharing a single init.mp4.
 *
 * @return array{stderr: string, duration: float}
 */
private function encodeFmp4AudioSegment(
    string $sourcePath,
    float $startTime,
    float $duration,
    array $job,
    string $segmentOutputPath,
    bool $keepInitOnly,
    ?string $initOutputPath = null,
): array {
    $profile = AudioProfile::fromString($job['audio_profile_name'] ?? 'streaming_stereo');
    $codecOptions = AudioProcessingRules::codecOptions($profile);
    $sampleRate = (int) ($job['sample_rate'] ?? 48000);
    $channels = (int) ($job['channels'] ?? 2);
    $af = $this->filterArg('af', $job['audio_filters'] ?? '');

    $tmpDir = dirname($segmentOutputPath) . '/.tmp_' . uniqid('audio', true);
    if (!is_dir($tmpDir)) {
        mkdir($tmpDir, 0755, true);
    }

    $playlistPath = $tmpDir . '/audio.m3u8';
    $segmentPattern = $tmpDir . '/seg_%d.m4s';

    $cmd = sprintf(
        '%s -y -ss %.6f -t %.6f -i %s'
        . ' -vn'
        . ' %s -ar %d -ac %d'
        . ' %s'
        . ' -f hls -hls_segment_type fmp4 -hls_time %d -hls_playlist_type vod'
        . ' -hls_segment_filename %s'
        . ' %s',
        self::FFMPEG_PATH,
        $startTime,
        $duration,
        escapeshellarg($sourcePath),
        $codecOptions,
        $sampleRate,
        $channels,
        $af,
        (int) ceil($duration),
        escapeshellarg($segmentPattern),
        escapeshellarg($playlistPath),
    );

    $result = $this->exec($cmd, 300);
    if ($result['code'] !== 0) {
        $this->cleanupDir($tmpDir);
        throw new RuntimeException(
            'Audio segment encoding failed: ' . ($result['stderr'] ?: 'unknown error'),
        );
    }

    $initSrc = $tmpDir . '/init.mp4';
    $segmentSrc = $tmpDir . '/seg_0.m4s';

    if (!is_file($initSrc) || !is_file($segmentSrc)) {
        $this->cleanupDir($tmpDir);
        throw new RuntimeException('HLS muxer did not produce expected init/segment files');
    }

    if ($keepInitOnly) {
        $this->atomicWriteWithLock($initSrc, $segmentOutputPath);
    } else {
        $this->atomicWriteWithLock($segmentSrc, $segmentOutputPath);
        if ($initOutputPath !== null) {
            $this->atomicWriteWithLock($initSrc, $initOutputPath);
        }
    }

    $this->cleanupDir($tmpDir);

    return [
        'stderr' => $result['stderr'] ?? '',
        'duration' => $this->parseDurationFromStderr($result['stderr'] ?? '', $duration),
    ];
}

