    public function getAudioManifest(PublicId $jobPublicId, string $language): string
    {
        $job = $this->jobRepository->findByPublicId($jobPublicId);
        if ($job === null) {
            return $this->manifestGenerator->generateAudioManifest($language, '', []);
        }

        $initSegmentPath = sprintf(
            '/api/transcode/%s/audio/%s/init.mp4',
            $job->getPublicId()->toString(),
            $language,
        );
        $initSegmentUrl = $this->streamAuth->signUrl($initSegmentPath)['url'];

        $signedSegments = [];
        foreach ($this->buildSegmentDurations($job) as $index => $duration) {
            $segmentPath = sprintf('/api/transcode/%s/audio/%s/seg_%d.m4s', $job->getPublicId()->toString(), $language, $index);
            $signedSegments[$index] = [
                'url' => $this->streamAuth->signUrl($segmentPath)['url'],
                'duration' => $duration,
            ];
        }

        return $this->manifestGenerator->generateAudioManifest($language, $initSegmentUrl, $signedSegments);
    }

