    public function resolveAudioSegmentAvailability(PublicId $jobPublicId, string $language, int $segmentIndex): ?array
    {
        $job = $this->jobRepository->findByPublicId($jobPublicId);
        if ($job === null) {
            return null;
        }

        $totalSegments = $job->getTotalSegments();
        if ($totalSegments > 0 && ($segmentIndex < 0 || $segmentIndex >= $totalSegments)) {
            return null;
        }

        $path = $this->storage->resolveAudioSegmentPath($job->getVideoId(), $language, $segmentIndex);

        return [
