    private function pollResult(string $jobId, int $maxWaitSeconds = 30): ?array
    {
        $key = CpuProcessPool::resultKey('analyze_loudness', $jobId);
        $iterations = (int) ($maxWaitSeconds / 0.5);

        for ($i = 0; $i < $iterations; $i++) {
            $result = $this->processPool->readResult($key);
            if ($result !== null) {
                if ($result['status'] === 'ok' && $result['data'] !== '') {
                    return $this->jsonEncoder->decode($result['data'], 'json');
                }

                return null;
            }

            Async::sleep(0.5);
        }

        return null;
    }

    /**
     * Returns a sibling job's measured loudness for the same video, or [] if
     * no active sibling has measured it yet.
     *
     * @return array<string, mixed>
     */
    private function findSiblingLoudness(TranscodeJob $job): array
    {
        foreach ($this->jobPort->findActiveByVideo($job->getVideoId()) as $sibling) {
            if ($sibling->getId()->equals($job->getId())) {
                continue;
            }
            $siblingLoudness = $sibling->getMeasuredLoudness();
            if ($siblingLoudness !== []) {
                return $siblingLoudness;
            }
        }

        return [];
    }

    /**
     * The loudness-analysis leader is the active job with the lowest tier
     * height for the video (ties broken by job id) — deterministic across
     * workers, so exactly one tier dispatches the full-file analysis.
     */
    private function isLoudnessLeader(TranscodeJob $job, QualityTier $tier): bool
    {
        foreach ($this->jobPort->findActiveByVideo($job->getVideoId()) as $sibling) {
            if ($sibling->getId()->equals($job->getId())) {
                continue;
            }
            $siblingTier = QualityTier::fromString($sibling->getQualityTierName());
            if ($siblingTier->height < $tier->height) {
                return false;
            }
            if ($siblingTier->height === $tier->height
                && strcmp($sibling->getId()->toString(), $job->getId()->toString()) < 0) {
                return false;
            }
        }

        return true;
    }

    /**
     * Polls the database for a sibling's measured loudness until the leader
     * delivers or the budget runs out. Returns [] on timeout — the caller
     * then falls back to dynamic normalization.
     *
     * @return array<string, mixed>
     */
    private function waitForSiblingLoudness(TranscodeJob $job, int $maxWaitSeconds): array
    {
        $elapsed = 0.0;
        while ($elapsed < $maxWaitSeconds) {
            $loudness = $this->findSiblingLoudness($job);
            if ($loudness !== []) {
                $job->setMeasuredLoudness($loudness);
                $this->jobPort->save($job);

                return $loudness;
            }

            Async::sleep(1.0);
            $elapsed += 1.0;
        }

        return [];
    }

    /**
     * Dispatch only the first audio segment for a language synchronously.
     *
     * This primes the audio track so players can start playback without waiting
     * for the full video segment queue to drain.
     *
     * @param string $language BCP-47 language tag
     */
    private function dispatchFirstAudioSegment(
        TranscodeJob $job,
        string $sourcePath,
        string $language,
        AudioProfile $audioProfile,
        string $audioFilters,
        int $totalSegments,
    ): void {
        $segmentDuration = SegmentEncoder::getSegmentDuration();
        $audioProfileData = $audioProfile->jsonSerialize();
        $audioSegmentMap = $job->getAudioSegmentMap();
        $key = sprintf('%s:%d', $language, 0);
        if (isset($audioSegmentMap[$key])) {
            return;
        }

        $outputPath = $this->storage->resolveAudioSegmentPath($job->getVideoId(), $language, 0);
        if ($this->storage->exists($outputPath) && filesize($outputPath) > 0) {
            $fileSize = filesize($outputPath);
            $job->markAudioSegmentCompleted($language, 0, $outputPath, $fileSize, $segmentDuration);

            return;
        }

        $this->processPool->encodeAudioSegment(
            $job, 0, $sourcePath, 0.0, $segmentDuration,
            $audioProfileData, $audioFilters, $language, $outputPath,
        );

        $resultKey = sprintf('encode_audio_seg:%s:%s:%d', $job->getId()->toString(), $language, 0);
        $inFlight = [$resultKey => ['index' => 0, 'path' => $outputPath]];

        while ($inFlight !== []) {
            $completed = $this->scanForCompletedResult($inFlight);
            if ($completed !== null) {
                $entry = $inFlight[$completed['key']];
                unset($inFlight[$completed['key']]);

                $duration = (float) ($completed['data']['duration'] ?? $segmentDuration);
                $fileSize = file_exists($entry['path']) ? filesize($entry['path']) : 0;
                if ($fileSize > 0) {
                    $job->markAudioSegmentCompleted($language, $entry['index'], $entry['path'], $fileSize, $duration);
                }

                continue;
            }

            Async::sleep(0.1);
        }
    }

    /**
     * Dispatch audio segments with sliding window, matching the video segment pattern.
     *
     * @param string $language BCP-47 language tag
     */
    private function dispatchAudioSegments(
        TranscodeJob $job,
        string $sourcePath,
        string $language,
        AudioProfile $audioProfile,
        string $audioFilters,
        int $totalSegments,
    ): void {
        $segmentDuration = SegmentEncoder::getSegmentDuration();
        $audioProfileData = $audioProfile->jsonSerialize();

        // Build pending list, skipping already-completed audio segments
        $pendingKeys = [];
        $pending = [];
        $audioSegmentMap = $job->getAudioSegmentMap();

        for ($i = 0; $i < $totalSegments; $i++) {
            $key = sprintf('%s:%d', $language, $i);
            if (isset($audioSegmentMap[$key])) {
                continue;
            }
            $outputPath = $this->storage->resolveAudioSegmentPath($job->getVideoId(), $language, $i);
            if ($this->storage->exists($outputPath)) {
                $fileSize = filesize($outputPath);
                if ($fileSize > 0) {
                    $job->markAudioSegmentCompleted($language, $i, $outputPath, $fileSize, $segmentDuration);
                    continue;
                }
            }
            $pendingKeys[] = $i;
            $pending[] = $outputPath;
        }

        if ($pendingKeys === []) {
            return;
        }

        $dispatched = 0;
        $total = count($pendingKeys);
        $windowSize = min(2, $this->processPool->getWorkerCount()); // Share workers across concurrent jobs
        $inFlight = [];

        while ($dispatched < $total || $inFlight !== []) {
            // Fill window
            while ($dispatched < $total && count($inFlight) < $windowSize) {
                $segmentIndex = $pendingKeys[$dispatched];
                $outputPath = $pending[$dispatched];
                $startTime = (float) ($segmentIndex * $segmentDuration);

                $this->processPool->encodeAudioSegment(
                    $job, $segmentIndex, $sourcePath, $startTime, $segmentDuration,
                    $audioProfileData, $audioFilters, $language, $outputPath,
                );

                $key = sprintf('encode_audio_seg:%s:%s:%d', $job->getId()->toString(), $language, $segmentIndex);
                $inFlight[$key] = ['index' => $segmentIndex, 'path' => $outputPath];
                $dispatched++;
            }

            // Poll for completion
            if ($inFlight !== []) {
                $completed = $this->scanForCompletedResult($inFlight);
                if ($completed !== null) {
                    $entry = $inFlight[$completed['key']];
                    unset($inFlight[$completed['key']]);

                    $duration = (float) ($completed['data']['duration'] ?? $segmentDuration);
                    $fileSize = file_exists($entry['path']) ? filesize($entry['path']) : 0;
                    if ($fileSize > 0) {
                        $job->markAudioSegmentCompleted($language, $entry['index'], $entry['path'], $fileSize, $duration);

                        $this->incrementPersistCounter($job->getId());
                        if ($this->shouldPersist($job->getId())) {
                            $this->jobPort->save($job);
                        }
                    }
                }
            }

            if ($inFlight === [] && $dispatched >= $total) {
                break;
            }

            Async::sleep(0.1);
        }

        // Always persist on completion of all audio segments
        $this->jobPort->save($job);
        $this->statePersister->persist($job);
        $this->clearPersistCounter($job->getId());
    }

